TICK_MS = 100
next_tick = now_ms() + TICK_MS
while True:
    timeout = max(0, next_tick - now_ms())
    for fd, ev in epoll.poll(timeout / 1000):  # wake on I/O or tick
        for msg in read_frames(fd):
            queues[fd].append(msg)              # queue, don't simulate
    if now_ms() >= next_tick:
        for fd, q in queues.items():
            apply_inputs(world, players[fd], q); q.clear()
        step_physics(world, TICK_MS)
        broadcast(encode_changes(world))
        next_tick += TICK_MS

function onServerState(msg) {
  x = msg.x                 // authoritative position
  world = msg.world         // other players, walls
  pending = pending.filter(i => i.seq > msg.lastSeq)
  for (const i of pending) {
    x = applyInput(x, i, world)  // replay unacked
  }
  render(x)
}
